package com.cosmicpve.upgrade;
import com.cosmicpve.CosmicPVE;import com.cosmicpve.combat.api.CombatContext;import com.cosmicpve.combat.api.DamageChannel;import com.cosmicpve.combat.pipeline.IncomingDamageContribution;import com.cosmicpve.combat.pipeline.IncomingDamageContributor;import com.cosmicpve.combat.pipeline.OutgoingDamageContribution;import com.cosmicpve.combat.pipeline.OutgoingDamageContributor;import java.util.List;import net.minecraft.world.entity.player.Player;
public final class PlayerUpgradeCombatContributor implements OutgoingDamageContributor,IncomingDamageContributor { private final PlayerUpgradeService service=new PlayerUpgradeService(); @Override public List<OutgoingDamageContribution> resolve(CombatContext c){if(c.channel()!=DamageChannel.ORDINARY||!(c.attacker() instanceof Player p))return List.of();double bonus=service.tier(p,PlayerUpgrade.MORE_DAMAGE)*.01;return bonus==0?List.of():List.of(new OutgoingDamageContribution(CosmicPVE.id("player_upgrade_more_damage"),bonus));}@Override public List<IncomingDamageContribution> resolveIncoming(CombatContext c){if(c.channel()!=DamageChannel.ORDINARY||!(c.target() instanceof Player p))return List.of();double reduction=service.tier(p,PlayerUpgrade.LESS_DAMAGE)*.01;return reduction==0?List.of():List.of(new IncomingDamageContribution(CosmicPVE.id("player_upgrade_less_damage"),1-reduction));}}
